export const PYTHON_VERSION_FILE = "3.11.8\n";

export const RUNTIME_TXT = "python-3.11.8\n";

export const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>MP4 Archive Consolidator</title>\n  <script src=\"https://cdn.tailwindcss.com\"></script>\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\">\n  <link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600&family=Plus+Jakarta+Sans:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n  <style>\n    body { font-family: 'Plus Jakarta Sans', sans-serif; }\n    code, pre, .font-mono { font-family: 'JetBrains Mono', monospace; }\n  </style>\n</head>\n<body class=\"bg-slate-50 text-slate-800 min-h-screen flex flex-col antialiased\">\n\n  <!-- COMPULSORY ADMIN AUTHENTICATION GATE (Client-side & server lock) -->\n  <div id=\"compulsoryAuthGate\" class=\"fixed inset-0 z-50 bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-4\">\n    <div class=\"bg-white rounded-2xl shadow-2xl max-w-md w-full p-6 sm:p-8 border border-slate-200\">\n      <div class=\"w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center mx-auto mb-4 shadow-inner\">\n        <svg class=\"w-7 h-7\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n          <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z\"/>\n        </svg>\n      </div>\n      <div class=\"text-center mb-6\">\n        <h2 class=\"text-lg font-bold text-slate-900 tracking-tight\">Admin Authentication Required</h2>\n        <p class=\"text-xs text-slate-500 mt-1.5 leading-relaxed\">\n          Admin password compulsory hai. Iske bina client-side encryption, consolidation, extraction ya koi bhi operation run nahi hoga.\n        </p>\n      </div>\n\n      <div class=\"space-y-4\">\n        <div>\n          <label class=\"block text-xs font-semibold text-slate-700 uppercase tracking-wider mb-1.5\">\n            Admin Password (ADMIN_PASSWORD)\n          </label>\n          <div class=\"relative\">\n            <input \n              type=\"password\" \n              id=\"gatePasswordInput\" \n              placeholder=\"Enter server ADMIN_PASSWORD\" \n              class=\"w-full px-4 py-2.5 rounded-xl border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm font-mono\"\n              onkeydown=\"if(event.key==='Enter') verifyAndUnlockGate()\"\n            />\n            <button \n              type=\"button\" \n              onclick=\"togglePasswordVisibility('gatePasswordInput')\" \n              class=\"absolute right-3 top-2.5 text-xs text-slate-400 hover:text-slate-600 font-medium\"\n            >\n              Toggle\n            </button>\n          </div>\n          <p id=\"gateErrorText\" class=\"hidden text-xs text-rose-600 font-medium mt-1.5\">\n            Incorrect admin password. Access denied.\n          </p>\n        </div>\n\n        <button \n          id=\"gateUnlockBtn\" \n          onclick=\"verifyAndUnlockGate()\" \n          class=\"w-full py-2.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-semibold text-sm rounded-xl shadow-sm transition flex items-center justify-center space-x-2\"\n        >\n          <span>Unlock & Authenticate</span>\n          <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\"/>\n          </svg>\n        </button>\n\n        <p class=\"text-[11px] text-slate-400 text-center\">\n          Configured in Render Environment variables as <code class=\"bg-slate-100 px-1 py-0.5 rounded text-slate-600\">ADMIN_PASSWORD</code>\n        </p>\n      </div>\n    </div>\n  </div>\n\n  <!-- Navigation Header -->\n  <header class=\"bg-white border-b border-slate-200 sticky top-0 z-30 shadow-xs\">\n    <div class=\"max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between\">\n      <div class=\"flex items-center space-x-3\">\n        <div class=\"w-9 h-9 rounded-lg bg-indigo-600 flex items-center justify-center text-white font-bold shadow-sm\">\n          <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z\" />\n          </svg>\n        </div>\n        <div>\n          <h1 class=\"text-base font-bold text-slate-900 tracking-tight\">MP4 Archive Consolidator</h1>\n          <p class=\"text-xs text-slate-500 font-medium\">Single-User Resilient Storage Pipeline</p>\n        </div>\n      </div>\n\n      <div class=\"flex items-center space-x-2 sm:space-x-3\">\n        <!-- Drive Diagnosis Button -->\n        <button \n          onclick=\"openDriveDiagnoseModal()\" \n          class=\"px-3 py-1.5 text-xs font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 border border-slate-300 rounded-lg transition flex items-center space-x-1.5\"\n        >\n          <svg class=\"w-3.5 h-3.5 text-indigo-600\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 00-9.78 2.096A4.001 4.001 0 003 15z\" />\n          </svg>\n          <span class=\"hidden sm:inline\">Google Drive Check</span>\n          <span class=\"sm:hidden\">Drive</span>\n        </button>\n\n        <!-- Auth Status Badge & Lock Button -->\n        <div id=\"authBadge\" class=\"hidden items-center space-x-1 px-2.5 py-1 rounded-full text-xs font-medium bg-emerald-50 text-emerald-700 border border-emerald-200\">\n          <span class=\"w-1.5 h-1.5 rounded-full bg-emerald-500\"></span>\n          <span class=\"hidden sm:inline\">Admin</span>\n        </div>\n\n        <button \n          id=\"authLockBtn\" \n          onclick=\"lockSystem()\" \n          title=\"Lock system / Switch Admin Key\"\n          class=\"px-2.5 py-1.5 text-xs font-medium text-slate-600 hover:text-slate-900 bg-slate-100 hover:bg-slate-200 border border-slate-300 rounded-lg transition flex items-center space-x-1\"\n        >\n          <svg class=\"w-3.5 h-3.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z\" />\n          </svg>\n          <span class=\"hidden sm:inline\">Lock</span>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <!-- Google Drive Diagnostic Modal -->\n  <div id=\"driveDiagnoseModal\" class=\"hidden fixed inset-0 z-50 bg-slate-950/70 backdrop-blur-xs flex items-center justify-center p-4\">\n    <div class=\"bg-white rounded-2xl shadow-xl max-w-lg w-full p-6 border border-slate-200 space-y-4\">\n      <div class=\"flex items-center justify-between border-b border-slate-100 pb-3\">\n        <div class=\"flex items-center space-x-2\">\n          <div class=\"w-7 h-7 rounded-lg bg-indigo-50 text-indigo-600 flex items-center justify-center\">\n            <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 00-9.78 2.096A4.001 4.001 0 003 15z\" />\n            </svg>\n          </div>\n          <h3 class=\"text-sm font-bold text-slate-900\">Google Drive Folder Integration Check</h3>\n        </div>\n        <button onclick=\"closeDriveDiagnoseModal()\" class=\"text-slate-400 hover:text-slate-600 text-sm\">\u2715</button>\n      </div>\n\n      <div id=\"driveDiagnoseLoading\" class=\"py-6 text-center text-xs text-slate-500\">\n        Checking Google Drive connection and folder permissions...\n      </div>\n\n      <div id=\"driveDiagnoseContent\" class=\"hidden space-y-3 text-xs\">\n        <div id=\"driveStatusBanner\" class=\"p-3 rounded-xl border\"></div>\n\n        <div class=\"space-y-1\">\n          <span class=\"font-semibold text-slate-700\">Service Account Email:</span>\n          <div class=\"flex items-center space-x-2\">\n            <input id=\"driveServiceAccountEmail\" readonly class=\"w-full bg-slate-50 border border-slate-200 rounded-lg px-2.5 py-1.5 font-mono text-[11px] text-slate-700 select-all\" />\n            <button onclick=\"copyServiceAccountEmail()\" class=\"px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-semibold rounded-lg shrink-0\">Copy</button>\n          </div>\n          <p class=\"text-[11px] text-slate-400\">Google Drive me ja kar apne folder ko is email ke saath \"Editor\" share karein.</p>\n        </div>\n\n        <div class=\"p-3 bg-amber-50 border border-amber-200 rounded-xl text-amber-900 space-y-1.5\">\n          <div class=\"font-bold flex items-center space-x-1.5\">\n            <span>Folder me files kyu nahi dikhti? (Important Fix)</span>\n          </div>\n          <ol class=\"list-decimal list-inside space-y-1 text-[11px] leading-relaxed text-amber-800\">\n            <li>Google Drive open karein: <a href=\"https://drive.google.com\" target=\"_blank\" class=\"underline font-semibold\">drive.google.com</a></li>\n            <li>Apne folder pe Right-click karein aur <strong>\"Share\"</strong> pe click karein.</li>\n            <li>Upar diye gaye Service Account email ko paste karein aur role <strong>\"Editor\"</strong> select karein.</li>\n            <li>Render me environment variable <code class=\"bg-amber-100 px-1 rounded\">DRIVE_FOLDER_ID</code> me apne folder ka exact ID daalein.</li>\n          </ol>\n        </div>\n      </div>\n\n      <div class=\"flex justify-end pt-2\">\n        <button onclick=\"closeDriveDiagnoseModal()\" class=\"px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 text-xs font-semibold rounded-lg\">Close</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- Main Content Container -->\n  <main class=\"flex-1 max-w-6xl w-full mx-auto px-4 sm:px-6 py-8\">\n\n    <!-- Mode Selector Tabs -->\n    <div class=\"flex space-x-2 mb-6 border-b border-slate-200\">\n      <button id=\"tabConsolidate\" onclick=\"switchTab('consolidate')\" class=\"px-4 py-2.5 text-sm font-semibold border-b-2 border-indigo-600 text-indigo-600 transition-colors\">\n        Consolidate & Stream Archive\n      </button>\n      <button id=\"tabExtract\" onclick=\"switchTab('extract')\" class=\"px-4 py-2.5 text-sm font-semibold border-b-2 border-transparent text-slate-500 hover:text-slate-800 transition-colors\">\n        Extract & Decrypt Payload\n      </button>\n    </div>\n\n    <!-- TAB 1: CONSOLIDATION FORM -->\n    <div id=\"viewConsolidate\" class=\"space-y-6\">\n      <form id=\"consolidateForm\" onsubmit=\"handleConsolidateSubmit(event)\" class=\"bg-white border border-slate-200 rounded-xl p-6 shadow-xs space-y-6\">\n        \n        <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n          \n          <!-- Large Data File Input -->\n          <div class=\"space-y-2\">\n            <label class=\"block text-sm font-semibold text-slate-700\">\n              1. Large Data File <span class=\"text-xs font-normal text-slate-400\">(Archive backup, up to 1GB)</span>\n            </label>\n            <div id=\"dataDropZone\" class=\"border-2 border-dashed border-slate-300 hover:border-indigo-400 rounded-xl p-6 text-center transition-colors cursor-pointer bg-slate-50\">\n              <input type=\"file\" id=\"dataFile\" name=\"data_file\" class=\"hidden\" required onchange=\"updateFileLabel('dataFile', 'dataFileName')\" />\n              <div class=\"flex flex-col items-center\">\n                <svg class=\"w-8 h-8 text-slate-400 mb-2\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12\" />\n                </svg>\n                <p id=\"dataFileName\" class=\"text-sm font-medium text-slate-600\">Choose data backup or drag here</p>\n                <p class=\"text-xs text-slate-400 mt-1\">TAR, ZIP, ISO, DB, BIN, or raw data</p>\n              </div>\n            </div>\n          </div>\n\n          <!-- Carrier MP4 File Input -->\n          <div class=\"space-y-2\">\n            <label class=\"block text-sm font-semibold text-slate-700\">\n              2. Carrier MP4 Video <span class=\"text-xs font-normal text-slate-400\">(Short video intro, up to 200MB)</span>\n            </label>\n            <div id=\"carrierDropZone\" class=\"border-2 border-dashed border-slate-300 hover:border-indigo-400 rounded-xl p-6 text-center transition-colors cursor-pointer bg-slate-50\">\n              <input type=\"file\" id=\"carrierFile\" name=\"carrier_file\" accept=\"video/mp4\" class=\"hidden\" required onchange=\"updateFileLabel('carrierFile', 'carrierFileName')\" />\n              <div class=\"flex flex-col items-center\">\n                <svg class=\"w-8 h-8 text-slate-400 mb-2\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z\" />\n                  <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M21 12a9 9 0 11-18 0 9 9 0 0118 0z\" />\n                </svg>\n                <p id=\"carrierFileName\" class=\"text-sm font-medium text-slate-600\">Choose .mp4 carrier or drag here</p>\n                <p class=\"text-xs text-slate-400 mt-1\">Must be standard MP4 container with fast-start/moov</p>\n              </div>\n            </div>\n          </div>\n\n        </div>\n\n        <!-- Reference Key (Password) Input -->\n        <div class=\"space-y-2\">\n          <label for=\"referenceKey\" class=\"block text-sm font-semibold text-slate-700\">\n            3. User Reference Key <span class=\"text-xs font-normal text-slate-400\">(Secret password for PBKDF2 + AES-CTR payload encryption)</span>\n          </label>\n          <div class=\"relative\">\n            <input \n              type=\"password\" \n              id=\"referenceKey\" \n              name=\"reference_key\" \n              required \n              placeholder=\"Enter encryption reference key (e.g., strong passphrase)\"\n              class=\"w-full px-4 py-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm font-mono\" \n            />\n            <button type=\"button\" onclick=\"togglePasswordVisibility('referenceKey')\" class=\"absolute right-3 top-2.5 text-xs text-slate-400 hover:text-slate-600 font-medium\">\n              Toggle\n            </button>\n          </div>\n          <p class=\"text-xs text-slate-500\">\n            This key encrypts the payload via AES-CTR. It is encrypted with server MASTER_ENCRYPTION_KEY (AES-256-GCM) and logged to Google Drive.\n          </p>\n        </div>\n\n        <!-- Submit Button -->\n        <div class=\"pt-2 flex items-center justify-between\">\n          <div class=\"text-xs text-slate-400\">\n            Resilient streaming: Zero in-memory buffer, automatic temporary disk purge.\n          </div>\n          <button \n            type=\"submit\" \n            id=\"startBtn\"\n            class=\"px-6 py-2.5 bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 text-white font-medium text-sm rounded-lg shadow-sm transition flex items-center space-x-2\"\n          >\n            <span>Start Resilient Consolidation</span>\n            <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n              <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M14 5l7 7m0 0l-7 7m7-7H3\" />\n            </svg>\n          </button>\n        </div>\n      </form>\n\n      <!-- Active Consolidation Progress Card (No raw log stream) -->\n      <div id=\"progressCard\" class=\"hidden bg-white border border-slate-200 rounded-xl p-6 shadow-xs space-y-4\">\n        <div class=\"flex items-center justify-between\">\n          <div class=\"flex items-center space-x-2.5\">\n            <span class=\"relative flex h-3 w-3\">\n              <span id=\"pulsePing\" class=\"animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75\"></span>\n              <span id=\"pulseDot\" class=\"relative inline-flex rounded-full h-3 w-3 bg-indigo-600\"></span>\n            </span>\n            <div>\n              <h3 class=\"text-sm font-bold text-slate-900\" id=\"progressTitle\">Pipeline Execution in Progress</h3>\n              <p class=\"text-xs text-slate-500 font-medium mt-0.5\" id=\"progressStage\">Initializing temporary storage...</p>\n            </div>\n          </div>\n          <span id=\"progressPercent\" class=\"text-2xl font-bold font-mono text-indigo-600\">0%</span>\n        </div>\n\n        <!-- Progress Bar -->\n        <div class=\"w-full bg-slate-100 rounded-full h-3.5 overflow-hidden p-0.5 border border-slate-200/60\">\n          <div id=\"progressBar\" class=\"bg-gradient-to-r from-indigo-500 to-indigo-600 h-full rounded-full transition-all duration-300 ease-out\" style=\"width: 0%\"></div>\n        </div>\n\n        <!-- Drive Diagnostics/Warning Notification Banner -->\n        <div id=\"driveWarningBanner\" class=\"hidden p-3 rounded-xl border bg-amber-50 border-amber-200 text-amber-900 text-xs flex items-start space-x-2\">\n          <svg class=\"w-4 h-4 text-amber-600 shrink-0 mt-0.5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z\"/></svg>\n          <span id=\"driveWarningText\" class=\"leading-relaxed\"></span>\n        </div>\n\n        <!-- Milestone Status Grid -->\n        <div class=\"grid grid-cols-1 sm:grid-cols-3 gap-3 pt-2\">\n          <div id=\"badgeDriveBackup\" class=\"p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-xs flex items-center space-x-2\">\n            <span class=\"w-2 h-2 rounded-full bg-slate-300\" id=\"dotDriveBackup\"></span>\n            <div class=\"truncate\">\n              <div class=\"font-semibold text-slate-700\">Google Drive Backup</div>\n              <div class=\"text-[11px] text-slate-400\" id=\"textDriveBackup\">Pending upload</div>\n            </div>\n          </div>\n          <div id=\"badgeKeylog\" class=\"p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-xs flex items-center space-x-2\">\n            <span class=\"w-2 h-2 rounded-full bg-slate-300\" id=\"dotKeylog\"></span>\n            <div class=\"truncate\">\n              <div class=\"font-semibold text-slate-700\">Zero-Knowledge Keylog</div>\n              <div class=\"text-[11px] text-slate-400\" id=\"textKeylog\">Pending AES-GCM</div>\n            </div>\n          </div>\n          <div id=\"badgeCarrier\" class=\"p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-xs flex items-center space-x-2\">\n            <span class=\"w-2 h-2 rounded-full bg-slate-300\" id=\"dotCarrier\"></span>\n            <div class=\"truncate\">\n              <div class=\"font-semibold text-slate-700\">Carrier Merge</div>\n              <div class=\"text-[11px] text-slate-400\" id=\"textCarrier\">Pending package</div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Download Action when Ready -->\n        <div id=\"downloadSection\" class=\"hidden pt-3 border-t border-slate-100 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3\">\n          <div class=\"text-xs text-slate-600\">\n            Consolidated MP4 generated successfully. Server temp files will be purged upon transfer.\n          </div>\n          <div class=\"flex items-center space-x-2\">\n            <button id=\"downloadBtn\" onclick=\"triggerDownload()\" class=\"px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-semibold rounded-lg shadow-sm flex items-center space-x-2 transition\">\n              <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4\" />\n              </svg>\n              <span>Download Playable MP4</span>\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- TAB 2: EXTRACTION FORM WITH DEDICATED PROGRESS BAR & PERCENTAGE -->\n    <div id=\"viewExtract\" class=\"hidden space-y-6\">\n      <form id=\"extractForm\" onsubmit=\"handleExtractSubmit(event)\" class=\"bg-white border border-slate-200 rounded-xl p-6 shadow-xs space-y-6\">\n        <div>\n          <h3 class=\"text-sm font-bold text-slate-900 mb-1\">Extract Data Payload from Consolidated MP4</h3>\n          <p class=\"text-xs text-slate-500\">Upload a consolidated MP4 file and provide the reference key to recover your original data backup.</p>\n        </div>\n\n        <!-- Consolidated MP4 File Input -->\n        <div class=\"space-y-2\">\n          <label class=\"block text-sm font-semibold text-slate-700\">Consolidated MP4 File</label>\n          <div id=\"extractDropZone\" class=\"border-2 border-dashed border-slate-300 hover:border-indigo-400 rounded-xl p-6 text-center transition-colors cursor-pointer bg-slate-50\">\n            <input type=\"file\" id=\"extractFile\" name=\"consolidated_file\" accept=\"video/mp4\" class=\"hidden\" required onchange=\"updateFileLabel('extractFile', 'extractFileName')\" />\n            <div class=\"flex flex-col items-center\">\n              <svg class=\"w-8 h-8 text-slate-400 mb-2\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n                <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"1.5\" d=\"M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12\" />\n              </svg>\n              <p id=\"extractFileName\" class=\"text-sm font-medium text-slate-600\">Select consolidated MP4</p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Password Input -->\n        <div class=\"space-y-2\">\n          <label for=\"extractKey\" class=\"block text-sm font-semibold text-slate-700\">Reference Key (Password)</label>\n          <div class=\"relative\">\n            <input \n              type=\"password\" \n              id=\"extractKey\" \n              name=\"reference_key\" \n              required \n              placeholder=\"Enter the password used during consolidation\"\n              class=\"w-full px-4 py-2.5 rounded-lg border border-slate-300 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm font-mono\" \n            />\n            <button type=\"button\" onclick=\"togglePasswordVisibility('extractKey')\" class=\"absolute right-3 top-2.5 text-xs text-slate-400 hover:text-slate-600 font-medium\">\n              Toggle\n            </button>\n          </div>\n        </div>\n\n        <button \n          type=\"submit\" \n          id=\"extractBtn\"\n          class=\"px-6 py-2.5 bg-slate-900 hover:bg-slate-800 text-white font-medium text-sm rounded-lg shadow-sm transition flex items-center space-x-2\"\n        >\n          <span>Extract & Decrypt Original File</span>\n          <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\">\n            <path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4\" />\n          </svg>\n        </button>\n      </form>\n\n      <!-- Extraction Progress Bar Card (Shows live percentage during extract) -->\n      <div id=\"extractProgressCard\" class=\"hidden bg-white border border-slate-200 rounded-xl p-6 shadow-xs space-y-4\">\n        <div class=\"flex items-center justify-between\">\n          <div class=\"flex items-center space-x-2.5\">\n            <span class=\"relative flex h-3 w-3\">\n              <span id=\"extractPulsePing\" class=\"animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75\"></span>\n              <span id=\"extractPulseDot\" class=\"relative inline-flex rounded-full h-3 w-3 bg-emerald-600\"></span>\n            </span>\n            <div>\n              <h3 class=\"text-sm font-bold text-slate-900\" id=\"extractProgressTitle\">Extraction & Decryption in Progress</h3>\n              <p class=\"text-xs text-slate-500 font-medium mt-0.5\" id=\"extractProgressStage\">Uploading consolidated MP4 to server...</p>\n            </div>\n          </div>\n          <span id=\"extractProgressPercent\" class=\"text-2xl font-bold font-mono text-emerald-600\">0%</span>\n        </div>\n\n        <!-- Extraction Progress Bar -->\n        <div class=\"w-full bg-slate-100 rounded-full h-3.5 overflow-hidden p-0.5 border border-slate-200/60\">\n          <div id=\"extractProgressBar\" class=\"bg-gradient-to-r from-emerald-500 to-emerald-600 h-full rounded-full transition-all duration-300 ease-out\" style=\"width: 0%\"></div>\n        </div>\n\n        <!-- Extraction Result Banner -->\n        <div id=\"extractResultSection\" class=\"hidden pt-3 border-t border-slate-100 flex items-center justify-between\">\n          <div class=\"text-xs text-slate-600\" id=\"extractResultMsg\">\n            Payload decrypted and downloaded successfully.\n          </div>\n          <button id=\"extractRedownloadBtn\" class=\"px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold rounded-lg shadow-sm transition\">\n            Download Again\n          </button>\n        </div>\n      </div>\n    </div>\n\n  </main>\n\n  <footer class=\"bg-white border-t border-slate-200 py-4 text-center text-xs text-slate-400\">\n    MP4 Archive Consolidator &bull; Production Architecture with Resumable Streaming & Zero-Knowledge Logs\n  </footer>\n\n  <script>\n    let currentTaskId = null;\n    let pollInterval = null;\n    let adminToken = localStorage.getItem(\"mp4_admin_key\") || \"\";\n    let lastExtractedBlob = null;\n    let lastExtractedFilename = \"extracted_payload.dat\";\n\n    // Enforce compulsory Admin Authentication immediately\n    function checkCompulsoryAuth() {\n      const gate = document.getElementById(\"compulsoryAuthGate\");\n      const badge = document.getElementById(\"authBadge\");\n      if (!adminToken) {\n        gate.classList.remove(\"hidden\");\n        badge.classList.add(\"hidden\");\n        badge.classList.remove(\"flex\");\n        document.getElementById(\"gatePasswordInput\").focus();\n      } else {\n        gate.classList.add(\"hidden\");\n        badge.classList.remove(\"hidden\");\n        badge.classList.add(\"flex\");\n      }\n    }\n    checkCompulsoryAuth();\n\n    async function verifyAndUnlockGate() {\n      const input = document.getElementById(\"gatePasswordInput\");\n      const errText = document.getElementById(\"gateErrorText\");\n      const btn = document.getElementById(\"gateUnlockBtn\");\n      const pass = input.value.trim();\n\n      if (!pass) {\n        errText.textContent = \"Please enter the admin password.\";\n        errText.classList.remove(\"hidden\");\n        return;\n      }\n\n      btn.disabled = true;\n      btn.innerHTML = `<span>Verifying...</span>`;\n\n      try {\n        const res = await fetch(\"/api/auth/verify\", {\n          method: \"POST\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: JSON.stringify({ admin_password: pass })\n        });\n        const data = await res.json();\n        if (res.ok && data.authenticated) {\n          adminToken = pass;\n          localStorage.setItem(\"mp4_admin_key\", pass);\n          errText.classList.add(\"hidden\");\n          checkCompulsoryAuth();\n        } else {\n          errText.textContent = data.error || \"Incorrect admin password. Access denied.\";\n          errText.classList.remove(\"hidden\");\n        }\n      } catch (err) {\n        // In local/offline or network timeout:\n        adminToken = pass;\n        localStorage.setItem(\"mp4_admin_key\", pass);\n        checkCompulsoryAuth();\n      } finally {\n        btn.disabled = false;\n        btn.innerHTML = `<span>Unlock & Authenticate</span>`;\n      }\n    }\n\n    function lockSystem() {\n      adminToken = \"\";\n      localStorage.removeItem(\"mp4_admin_key\");\n      document.getElementById(\"gatePasswordInput\").value = \"\";\n      document.getElementById(\"gateErrorText\").classList.add(\"hidden\");\n      checkCompulsoryAuth();\n    }\n\n    function requireAuthGuard() {\n      if (!adminToken) {\n        checkCompulsoryAuth();\n        return false;\n      }\n      return true;\n    }\n\n    // Google Drive Diagnosis\n    async function openDriveDiagnoseModal() {\n      if (!requireAuthGuard()) return;\n      const modal = document.getElementById(\"driveDiagnoseModal\");\n      const loading = document.getElementById(\"driveDiagnoseLoading\");\n      const content = document.getElementById(\"driveDiagnoseContent\");\n      modal.classList.remove(\"hidden\");\n      loading.classList.remove(\"hidden\");\n      content.classList.add(\"hidden\");\n\n      try {\n        const res = await fetch(\"/api/drive/diagnose\", {\n          headers: { \"X-Admin-Password\": adminToken }\n        });\n        const data = await res.json();\n        loading.classList.add(\"hidden\");\n        content.classList.remove(\"hidden\");\n\n        const banner = document.getElementById(\"driveStatusBanner\");\n        document.getElementById(\"driveServiceAccountEmail\").value = data.client_email || \"Not configured\";\n\n        if (data.configured && data.folder_accessible) {\n          banner.className = \"p-3 rounded-xl border bg-emerald-50 border-emerald-200 text-emerald-800\";\n          banner.innerHTML = `<strong>Google Drive Ready:</strong> Connected to folder <code>${data.folder_name}</code>. Uploads will appear directly in this folder!`;\n        } else if (data.configured && !data.folder_accessible) {\n          banner.className = \"p-3 rounded-xl border bg-rose-50 border-rose-200 text-rose-800\";\n          banner.innerHTML = `<strong>Folder Access Issue:</strong> ${data.error || 'Folder not accessible'}<br><span class=\"text-[11px] mt-1 block\">${data.instruction || ''}</span>`;\n        } else {\n          banner.className = \"p-3 rounded-xl border bg-amber-50 border-amber-200 text-amber-800\";\n          banner.innerHTML = `<strong>Setup Incomplete:</strong> ${data.error || data.instruction}`;\n        }\n      } catch (err) {\n        loading.textContent = \"Error checking Google Drive: \" + err.message;\n      }\n    }\n\n    function closeDriveDiagnoseModal() {\n      document.getElementById(\"driveDiagnoseModal\").classList.add(\"hidden\");\n    }\n\n    function copyServiceAccountEmail() {\n      const emailInput = document.getElementById(\"driveServiceAccountEmail\");\n      emailInput.select();\n      navigator.clipboard.writeText(emailInput.value);\n      alert(\"Service Account Email copied to clipboard: \" + emailInput.value);\n    }\n\n    function switchTab(tab) {\n      if (tab === 'consolidate') {\n        document.getElementById(\"viewConsolidate\").classList.remove(\"hidden\");\n        document.getElementById(\"viewExtract\").classList.add(\"hidden\");\n        document.getElementById(\"tabConsolidate\").className = \"px-4 py-2.5 text-sm font-semibold border-b-2 border-indigo-600 text-indigo-600 transition-colors\";\n        document.getElementById(\"tabExtract\").className = \"px-4 py-2.5 text-sm font-semibold border-b-2 border-transparent text-slate-500 hover:text-slate-800 transition-colors\";\n      } else {\n        document.getElementById(\"viewConsolidate\").classList.add(\"hidden\");\n        document.getElementById(\"viewExtract\").classList.remove(\"hidden\");\n        document.getElementById(\"tabConsolidate\").className = \"px-4 py-2.5 text-sm font-semibold border-b-2 border-transparent text-slate-500 hover:text-slate-800 transition-colors\";\n        document.getElementById(\"tabExtract\").className = \"px-4 py-2.5 text-sm font-semibold border-b-2 border-indigo-600 text-indigo-600 transition-colors\";\n      }\n    }\n\n    function setupDropZone(dropZoneId, inputId, labelId) {\n      const zone = document.getElementById(dropZoneId);\n      const input = document.getElementById(inputId);\n\n      zone.addEventListener(\"click\", () => {\n        if (!requireAuthGuard()) return;\n        input.click();\n      });\n      zone.addEventListener(\"dragover\", (e) => {\n        e.preventDefault();\n        zone.classList.add(\"border-indigo-500\", \"bg-indigo-50/30\");\n      });\n      zone.addEventListener(\"dragleave\", () => {\n        zone.classList.remove(\"border-indigo-500\", \"bg-indigo-50/30\");\n      });\n      zone.addEventListener(\"drop\", (e) => {\n        e.preventDefault();\n        zone.classList.remove(\"border-indigo-500\", \"bg-indigo-50/30\");\n        if (!requireAuthGuard()) return;\n        if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {\n          input.files = e.dataTransfer.files;\n          updateFileLabel(inputId, labelId);\n        }\n      });\n    }\n\n    setupDropZone(\"dataDropZone\", \"dataFile\", \"dataFileName\");\n    setupDropZone(\"carrierDropZone\", \"carrierFile\", \"carrierFileName\");\n    setupDropZone(\"extractDropZone\", \"extractFile\", \"extractFileName\");\n\n    function updateFileLabel(inputId, labelId) {\n      const input = document.getElementById(inputId);\n      const label = document.getElementById(labelId);\n      if (input.files && input.files.length > 0) {\n        const file = input.files[0];\n        const sizeMb = (file.size / (1024 * 1024)).toFixed(1);\n        label.innerHTML = `<span class=\"text-indigo-600 font-semibold\">${file.name}</span> (${sizeMb} MB)`;\n      }\n    }\n\n    function togglePasswordVisibility(id) {\n      const input = document.getElementById(id);\n      input.type = input.type === \"password\" ? \"text\" : \"password\";\n    }\n\n    // CONSOLIDATE SUBMISSION (Clean progress bar, percentage, zero raw log stream)\n    async function handleConsolidateSubmit(e) {\n      e.preventDefault();\n      if (!requireAuthGuard()) return;\n\n      const form = document.getElementById(\"consolidateForm\");\n      const formData = new FormData(form);\n\n      document.getElementById(\"progressCard\").classList.remove(\"hidden\");\n      document.getElementById(\"downloadSection\").classList.add(\"hidden\");\n      const driveWarn = document.getElementById(\"driveWarningBanner\");\n      if (driveWarn) driveWarn.classList.add(\"hidden\");\n      document.getElementById(\"startBtn\").disabled = true;\n      document.getElementById(\"startBtn\").classList.add(\"opacity-50\");\n\n      updateProgress(0, \"Uploading files to server temporary storage...\");\n\n      const xhr = new XMLHttpRequest();\n      xhr.open(\"POST\", \"/api/consolidate\", true);\n      xhr.setRequestHeader(\"X-Admin-Password\", adminToken);\n\n      xhr.upload.onprogress = function(event) {\n        if (event.lengthComputable) {\n          const uploadPct = Math.round((event.loaded / event.total) * 15);\n          updateProgress(uploadPct, `Uploading files to server (${uploadPct}%)...`);\n        }\n      };\n\n      xhr.onload = function() {\n        if (xhr.status === 200) {\n          const resp = JSON.parse(xhr.responseText);\n          currentTaskId = resp.task_id;\n          updateProgress(15, \"Files staged. Resilient cloud pipeline initiated...\");\n          startPolling(currentTaskId);\n        } else {\n          let err = \"Upload failed.\";\n          try { err = JSON.parse(xhr.responseText).error || err; } catch(_) {}\n          if (xhr.status === 401) {\n            err = \"Admin authentication required.\";\n            lockSystem();\n          }\n          updateProgress(0, \"Error: \" + err);\n          document.getElementById(\"startBtn\").disabled = false;\n          document.getElementById(\"startBtn\").classList.remove(\"opacity-50\");\n        }\n      };\n\n      xhr.onerror = function() {\n        updateProgress(0, \"Network error during file upload.\");\n        document.getElementById(\"startBtn\").disabled = false;\n        document.getElementById(\"startBtn\").classList.remove(\"opacity-50\");\n      };\n\n      xhr.send(formData);\n    }\n\n    function updateProgress(percent, stageText) {\n      document.getElementById(\"progressBar\").style.width = percent + \"%\";\n      document.getElementById(\"progressPercent\").textContent = percent + \"%\";\n      if (stageText) {\n        document.getElementById(\"progressStage\").textContent = stageText;\n      }\n    }\n\n    function startPolling(taskId) {\n      if (pollInterval) clearInterval(pollInterval);\n\n      pollInterval = setInterval(async () => {\n        try {\n          const res = await fetch(`/api/status/${taskId}`, {\n            headers: { \"X-Admin-Password\": adminToken }\n          });\n          if (!res.ok) return;\n\n          const data = await res.json();\n          updateProgress(data.progress, data.stage);\n\n          if (data.drive_warning) {\n            const warnBanner = document.getElementById(\"driveWarningBanner\");\n            const warnText = document.getElementById(\"driveWarningText\");\n            if (warnBanner && warnText) {\n              warnText.textContent = data.drive_warning;\n              warnBanner.classList.remove(\"hidden\");\n            }\n          }\n\n          // Update milestone badges cleanly without terminal text spam\n          if (data.data_drive_id) {\n            document.getElementById(\"dotDriveBackup\").className = \"w-2 h-2 rounded-full bg-emerald-500\";\n            if (data.drive_file_link) {\n              document.getElementById(\"textDriveBackup\").innerHTML = `<a href=\"${data.drive_file_link}\" target=\"_blank\" class=\"text-indigo-600 underline font-semibold\">View on Drive</a>`;\n            } else {\n              document.getElementById(\"textDriveBackup\").textContent = `ID: ${data.data_drive_id.substring(0, 10)}...`;\n            }\n          }\n          if (data.keylog_drive_id) {\n            document.getElementById(\"dotKeylog\").className = \"w-2 h-2 rounded-full bg-emerald-500\";\n            document.getElementById(\"textKeylog\").textContent = \"Keylog Stored (AES-GCM)\";\n          }\n\n          if (data.status === \"completed\") {\n            clearInterval(pollInterval);\n            document.getElementById(\"dotCarrier\").className = \"w-2 h-2 rounded-full bg-emerald-500\";\n            document.getElementById(\"textCarrier\").textContent = \"Merged & Playable\";\n            updateProgress(100, \"Consolidation complete! Playable MP4 archive is ready.\");\n            document.getElementById(\"downloadSection\").classList.remove(\"hidden\");\n            document.getElementById(\"startBtn\").disabled = false;\n            document.getElementById(\"startBtn\").classList.remove(\"opacity-50\");\n          } else if (data.status === \"failed\") {\n            clearInterval(pollInterval);\n            updateProgress(data.progress || 0, `Failed: ${data.error}`);\n            document.getElementById(\"startBtn\").disabled = false;\n            document.getElementById(\"startBtn\").classList.remove(\"opacity-50\");\n          }\n        } catch (e) {\n          console.error(\"Polling error:\", e);\n        }\n      }, 1000);\n    }\n\n    function triggerDownload() {\n      if (!currentTaskId) return;\n      window.location.href = `/api/download/${currentTaskId}`;\n    }\n\n    // EXTRACTION SUBMISSION WITH LIVE PROGRESS BAR AND PERCENTAGE\n    async function handleExtractSubmit(e) {\n      e.preventDefault();\n      if (!requireAuthGuard()) return;\n\n      const form = document.getElementById(\"extractForm\");\n      const formData = new FormData(form);\n      const btn = document.getElementById(\"extractBtn\");\n      const card = document.getElementById(\"extractProgressCard\");\n      const resultSection = document.getElementById(\"extractResultSection\");\n\n      btn.disabled = true;\n      btn.classList.add(\"opacity-50\");\n      card.classList.remove(\"hidden\");\n      resultSection.classList.add(\"hidden\");\n\n      updateExtractProgress(0, \"Initiating consolidated MP4 upload...\");\n\n      const xhr = new XMLHttpRequest();\n      xhr.open(\"POST\", \"/api/extract\", true);\n      xhr.responseType = \"blob\";\n      xhr.setRequestHeader(\"X-Admin-Password\", adminToken);\n\n      // Upload progress: 0% to 50%\n      xhr.upload.onprogress = function(event) {\n        if (event.lengthComputable) {\n          const pct = Math.round((event.loaded / event.total) * 50);\n          updateExtractProgress(pct, `Uploading consolidated MP4 (${pct * 2}%)...`);\n        }\n      };\n\n      // Server decryption phase simulation between 50% and 90%\n      let decryptTimer = setInterval(() => {\n        const cur = parseInt(document.getElementById(\"extractProgressPercent\").textContent) || 50;\n        if (cur < 92) {\n          updateExtractProgress(cur + 6, \"Parsing trailer, deriving PBKDF2 key & decrypting AES-CTR payload...\");\n        }\n      }, 350);\n\n      xhr.onload = function() {\n        clearInterval(decryptTimer);\n        if (xhr.status === 200) {\n          updateExtractProgress(100, \"Decryption complete! Original payload restored.\");\n\n          const blob = xhr.response;\n          lastExtractedBlob = blob;\n          const disposition = xhr.getResponseHeader('Content-Disposition');\n          let filename = \"extracted_payload.dat\";\n          if (disposition && disposition.indexOf('filename=') !== -1) {\n            const matches = /filename=\"([^\"]+)\"/.exec(disposition);\n            if (matches != null && matches[1]) filename = matches[1];\n          }\n          lastExtractedFilename = filename;\n\n          // Trigger download\n          downloadExtractedBlob(blob, filename);\n\n          // Show success message and download again button\n          resultSection.classList.remove(\"hidden\");\n          document.getElementById(\"extractResultMsg\").innerHTML = `<span class=\"text-emerald-700 font-semibold\">Success:</span> Restored <strong>${filename}</strong> (${(blob.size / 1024).toFixed(1)} KB).`;\n          document.getElementById(\"extractRedownloadBtn\").onclick = () => downloadExtractedBlob(lastExtractedBlob, lastExtractedFilename);\n\n          btn.disabled = false;\n          btn.classList.remove(\"opacity-50\");\n        } else {\n          updateExtractProgress(0, \"Extraction failed. Invalid password or corrupted carrier file.\");\n          btn.disabled = false;\n          btn.classList.remove(\"opacity-50\");\n          if (xhr.status === 401) {\n            lockSystem();\n          }\n        }\n      };\n\n      xhr.onerror = function() {\n        clearInterval(decryptTimer);\n        updateExtractProgress(0, \"Network error during extraction.\");\n        btn.disabled = false;\n        btn.classList.remove(\"opacity-50\");\n      };\n\n      xhr.send(formData);\n    }\n\n    function updateExtractProgress(percent, stageText) {\n      document.getElementById(\"extractProgressBar\").style.width = percent + \"%\";\n      document.getElementById(\"extractProgressPercent\").textContent = percent + \"%\";\n      if (stageText) {\n        document.getElementById(\"extractProgressStage\").textContent = stageText;\n      }\n    }\n\n    function downloadExtractedBlob(blob, filename) {\n      const url = window.URL.createObjectURL(blob);\n      const a = document.createElement('a');\n      a.href = url;\n      a.download = filename;\n      document.body.appendChild(a);\n      a.click();\n      a.remove();\n      setTimeout(() => window.URL.revokeObjectURL(url), 2000);\n    }\n  </script>\n</body>\n</html>\n";
